{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Use mean pairwise logistic loss with a 0.2 margin to encourage positive-negative separation. Preserve the existing samples, masks, GRU architecture, inference scores, and training settings.",
      "edits": [
        {
          "find": "    weights = torch.softmax(valid_neg.detach(), dim=0)\n    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * pairwise_loss).sum()",
          "replace": "    pairwise_loss = torch.nn.functional.softplus(0.2 + valid_neg - valid_pos)\n    return pairwise_loss.mean()"
        }
      ]
    }
  ],
  "change_summary": "Replace negative-score-weighted BPR with mean margin pairwise logistic loss for all four independently trained category models. No predictor changes are required."
}
